import { atom, update } from 'claude-code'
import type { EngineInterface, ModelEffort, Register } from 'claude-code'

import type { Consulta } from './lib'
import { DESCRICAO, ESQUEMA, lerConsulta, montarPedido, resumo, SISTEMA } from './lib'

type $ = EngineInterface

const consultas = atom({ plugin: 'segunda-opiniao', key: 'consultas' } as const, 0)

let modelo = 'opus'
let esforco: ModelEffort = 'high'

/** Pergunta ao outro modelo; devolve o texto ou um erro legível, nunca lança. */
async function consultar($: $, consulta: Consulta): Promise<{ texto: string; isErro: boolean }> {
  $.ui.toast(`🧠 Pedindo segunda opinião ao ${modelo}…`)
  const resposta = await $.model.complete({
    model: modelo,
    effort: esforco,
    maxTokens: 2000,
    timeoutMs: 120_000,
    system: SISTEMA,
    prompt: montarPedido(consulta),
  })
  const total = await update($, consultas, n => n + 1)
  $.ui.status(`🧠 ${total} segunda(s) opinião(ões)`)

  if (!resposta.isAnswered) {
    const motivo = resposta.reason === 'api-error' ? `erro da API: ${resposta.error}` : resposta.reason
    $.ui.toast(`🧠 O ${modelo} não respondeu (${motivo})`)
    return { texto: `A segunda opinião falhou: o ${modelo} não respondeu (${motivo}). Siga com o seu próprio julgamento ou tente de novo.`, isErro: true }
  }
  $.ui.toast(`🧠 ${modelo}: ${resumo(resposta.text)}`, { timeoutMs: 10_000 })

  return { texto: resposta.text.trim(), isErro: false }
}

export const register: Register = (on, options) => {
  modelo = String(options.modelo ?? 'opus')
  esforco = String(options.esforco ?? 'high') as ModelEffort

  on('session.start', async ($, e, next) => {
    // A ferramenta entra na lista que o modelo vê, como mcp__segunda-opiniao__segunda_opiniao.
    await $.tool.register({ name: 'segunda_opiniao', description: DESCRICAO, inputSchema: ESQUEMA })
    await $.command.register({
      name: 'segunda-opiniao',
      description: 'Pergunta direto ao outro modelo (o mesmo que o agente consulta)',
      argumentHint: '<pergunta>',
    })

    return next(e)
  })

  // Quem serve a ferramenta é este hook: o engine não tem implementação para ela.
  on('tool.call', { tool: /__segunda_opiniao$/ }, async ($, e) => {
    // Os argumentos do modelo chegam soltos em `e`, ao lado de `tool` e `tool_use_id`.
    const consulta = lerConsulta(e)
    if (consulta === undefined) return { result: 'Faltou a pergunta: mande o campo "pergunta".' }
    const { texto, isErro } = await consultar($, consulta)

    return { result: isErro ? texto : `Segunda opinião (${modelo}):\n\n${texto}` }
  })

  on('command.run', { command: 'segunda-opiniao' }, async ($, e) => {
    const pergunta = e.args.trim()
    if (pergunta === '') return { text: 'Uso: /segunda-opiniao <pergunta>' }
    const { texto } = await consultar($, { pergunta })

    return { text: `🧠 ${modelo}:\n\n${texto}` }
  })
}

