// Lógica pura do segunda-opiniao: o pedido ao revisor e a forma da resposta.

export const FOCOS = ['plano', 'bug', 'seguranca', 'design'] as const
export type Foco = (typeof FOCOS)[number]

export type Consulta = { pergunta: string; contexto?: string; foco?: Foco }

/** O que o agente lê na lista de ferramentas: é isso que o faz decidir usá-la. */
export const DESCRICAO =
  'Pede uma segunda opinião a outro modelo, um revisor cético. Use antes de decisões arriscadas ' +
  '(migração, exclusão de dados, mudança de arquitetura) ou quando estiver em dúvida entre abordagens. ' +
  'Mande a pergunta, o contexto necessário (trechos de código, o plano, o erro) e o foco.'

export const ESQUEMA = {
  type: 'object',
  properties: {
    pergunta: { type: 'string', description: 'O que você quer que o revisor avalie' },
    contexto: { type: 'string', description: 'Código, plano ou erro que o revisor precisa ver' },
    foco: { type: 'string', enum: [...FOCOS], description: 'Onde o revisor deve se concentrar' },
  },
  required: ['pergunta'],
}

const OLHAR: Record<Foco, string> = {
  plano: 'Procure passos faltando, ordem errada e riscos sem plano de volta.',
  bug: 'Procure a causa raiz, não só o sintoma, e casos de borda que quebram a correção.',
  seguranca: 'Procure injeção, segredos expostos, permissões largas demais e dados de usuário em risco.',
  design: 'Procure acoplamento, abstrações prematuras e o que vai doer na próxima mudança.',
}

export const SISTEMA =
  'Você é um engenheiro sênior cético dando uma segunda opinião a outro agente de código. ' +
  'Seja direto: comece pelo veredito (concordo / concordo com ressalvas / discordo), depois os riscos ' +
  'em ordem de gravidade e uma alternativa concreta se houver. No máximo 200 palavras. Responda em português do Brasil.'

export function montarPedido(consulta: Consulta): string {
  return [
    `Pergunta: ${consulta.pergunta}`,
    consulta.foco === undefined ? '' : `Foco: ${OLHAR[consulta.foco]}`,
    consulta.contexto === undefined ? '' : `Contexto:\n${consulta.contexto}`,
  ]
    .filter(Boolean)
    .join('\n\n')
}

/** Lê o input que o modelo mandou, tolerando campos ausentes ou fora do enum. */
export function lerConsulta(input: unknown): Consulta | undefined {
  const bruto = (input ?? {}) as Record<string, unknown>
  const pergunta = typeof bruto.pergunta === 'string' ? bruto.pergunta.trim() : ''
  if (pergunta === '') return undefined
  const foco = FOCOS.find(f => f === bruto.foco)
  const contexto = typeof bruto.contexto === 'string' && bruto.contexto.trim() !== '' ? bruto.contexto : undefined

  return { pergunta, contexto, foco }
}

/** Primeira linha, curta, para o toast. */
export function resumo(texto: string, limite = 90): string {
  const linha = texto.trim().split('\n')[0] ?? ''

  return linha.length > limite ? `${linha.slice(0, limite - 1)}…` : linha
}

